// harness v2 (SC-5859) — generated by `harness init`; change the template in ~/Development/harness, never this file
import { defineConfig } from '@playwright/test';
import { execFileSync } from 'node:child_process';
// No HARNESS_WEB_PORT → claim a free port from the OS and export it (workers inherit the env),
// so every run serves a fresh build instead of hitting whatever already holds a fixed port.
process.env.HARNESS_WEB_PORT ??= execFileSync(process.execPath, [
  '-e',
  "const s=require('net').createServer();s.listen(0,'127.0.0.1',()=>{process.stdout.write(String(s.address().port));s.close()})",
]).toString();
const PORT = Number(process.env.HARNESS_WEB_PORT);
export default defineConfig({
  testDir: 'e2e',
  fullyParallel: true,
  retries: 0,
  reporter: [['list']],
  expect: { toHaveScreenshot: { maxDiffPixelRatio: 0.002, animations: 'disabled' } },
  use: { baseURL: `http://127.0.0.1:${PORT}` },
  // Set HARNESS_WEB_CMD (or edit via `harness unlock`) to the command that serves the app on $PORT.
  // Never reuse a server this run did not start: a busy port fails fast instead of testing some other app.
  webServer: {
    command: process.env.HARNESS_WEB_CMD || `npm run -s serve -- --port ${PORT}`,
    url: `http://127.0.0.1:${PORT}`,
    reuseExistingServer: false,
    timeout: 120000,
  },
});
